const body = $json.body || {};

// Doctor can request specific date or default to today
const targetDateStr = body.date || $now.toFormat('yyyy-MM-dd');

// Credentials & Account IDs
const metaAccessToken = $env.META_ACCESS_TOKEN || 'EAAG_DENTALPIN_META_ACCESS_TOKEN';
const igUserId = $env.META_IG_USER_ID || '17841400000000000';
const fbPageId = $env.META_FB_PAGE_ID || '100000000000000';
const dentalpinApiBase = ($env.DENTALPIN_API_BASE_URL || 'https://dental-api-2z19.onrender.com').replace(/\/+$/, '');
const dentalpinSyncPath = $env.DENTALPIN_SYNC_PATH || '/api/v1/social_automation/insights';
const dentalpinSyncUrl = `${dentalpinApiBase}${dentalpinSyncPath}`;
const dentalpinApiKey = $env.DENTALPIN_API_KEY || '';

return [
  {
    json: {
      target_date: targetDateStr,
      requested_by: body.requested_by || 'Dr. Mokhtar',
      meta_access_token: metaAccessToken,
      ig_user_id: igUserId,
      fb_page_id: fbPageId,
      ig_account_id: 'dr_mokhtar_dental',
      fb_account_id: 'dr_mokhtar_cabinet',
      dentalpin_api_base: dentalpinApiBase,
      dentalpin_sync_url: dentalpinSyncUrl,
      dentalpin_api_key: dentalpinApiKey
    }
  }
];

const req = $('Parse Doctor Request & Date').first().json;

let igProfile = {};
let igInsights = [];
let fbProfile = {};
let fbInsights = [];

try {
  const res = $('Fetch Instagram Profile Live').first()?.json || {};
  if (!res.error) igProfile = res;
} catch (e) {}

try {
  const res = $('Fetch Instagram Insights Live').first()?.json || {};
  if (Array.isArray(res.data)) igInsights = res.data;
} catch (e) {}

try {
  const res = $('Fetch Facebook Profile Live').first()?.json || {};
  if (!res.error) fbProfile = res;
} catch (e) {}

try {
  const res = $('Fetch Facebook Insights Live').first()?.json || {};
  if (Array.isArray(res.data)) fbInsights = res.data;
} catch (e) {}

function extractVal(dataArr, metricName) {
  if (!Array.isArray(dataArr)) return 0;
  const item = dataArr.find(d => d && d.name === metricName);
  if (!item || !Array.isArray(item.values) || item.values.length === 0) return 0;
  const val = item.values[item.values.length - 1]?.value;
  return typeof val === 'number' ? val : (parseInt(val, 10) || 0);
}

const igFollowers = typeof igProfile.followers_count === 'number' ? igProfile.followers_count : 0;
const igReach = extractVal(igInsights, 'reach');
const igViews = extractVal(igInsights, 'profile_views');
const igClicks = extractVal(igInsights, 'website_clicks');

const fbFollowers = typeof fbProfile.followers_count === 'number'
  ? fbProfile.followers_count
  : (typeof fbProfile.fan_count === 'number' ? fbProfile.fan_count : 0);
const fbReach = extractVal(fbInsights, 'page_impressions_unique');
const fbViews = extractVal(fbInsights, 'page_views_total');
const fbClicks = extractVal(fbInsights, 'page_total_actions');

const igRecord = {
  platform: 'instagram',
  account_id: igProfile.username || req.ig_account_id,
  date: req.target_date,
  total_followers: igFollowers,
  reach: igReach,
  profile_views: igViews,
  website_clicks: igClicks,
  saves: 0
};

const fbRecord = {
  platform: 'facebook',
  account_id: fbProfile.name ? fbProfile.name.toLowerCase().replace(/[^a-z0-9_]/g, '_') : req.fb_account_id,
  date: req.target_date,
  total_followers: fbFollowers,
  reach: fbReach,
  profile_views: fbViews,
  website_clicks: fbClicks,
  saves: 0
};

return [
  {
    json: {
      sync_payload: {
        insights: [igRecord, fbRecord]
      },
      target_date: req.target_date,
      requested_by: req.requested_by,
      dentalpin_api_base: req.dentalpin_api_base,
      dentalpin_sync_url: req.dentalpin_sync_url,
      dentalpin_api_key: req.dentalpin_api_key,
      summary: {
        date: req.target_date,
        instagram: { followers: igFollowers, reach: igReach, views: igViews, clicks: igClicks },
        facebook: { followers: fbFollowers, reach: fbReach, views: fbViews, clicks: fbClicks }
      }
    }
  }
];
